WHERE v.deleted_at IS NULL
AND (v.status != #{scope.pending} OR v.occurred_on >= #{oldestPending})
AND v.status != #{scope.pending}

    AND (1 = 0
    OR v.student_id = #{scope.studentId}
    OR v.class_id = #{scope.classId}

        OR v.department_code IN
        #{dept}

    OR v.status = #{scope.approved}
    )

mapper.update:
UPDATE violation_record SET occurred_on = #{input.occurredOn}, type_code = #{input.typeCode}, department_code = #{department}, status = #{input.status}, handed_back_at = #{handedBackAt,jdbcType=BIGINT}, rejection_reason = NULL, appeal_label = #{appealLabel,jdbcType=VARCHAR}, version = version + 1
, student_id = #{student.id}, student_no = #{student.studentNo}, student_name = #{student.name}, class_id = #{student.classId}, class_name = #{student.className}, counselor = #{student.counselor}
WHERE id = #{id} AND version = #{input.version} AND deleted_at IS NULL

mapper.select:
SELECT v.occurred_on, v.student_no, v.student_name, v.class_name, v.counselor,
       d.name AS department_name, t.name AS type_name, v.reason, v.disposition,
       v.inspection_scope, v.remarks, v.status, v.inspection_label
FROM violation_record v JOIN department d ON d.code = v.department_code
JOIN violation_type t ON t.code = v.type_code
WHERE v.deleted_at IS NULL AND v.status != #{pending}
AND v.status != #{excluded}


ORDER BY v.occurred_on DESC, v.id DESC LIMIT #{limit}
